fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array is non-empty, we can safely iterate from 1 to arr.len() - 1
    for i in 1..arr.len() {
        // If any adjacent pair is out of order, it's not nondecreasing
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    // If we never found an out‐of‐order pair, it's sorted
    true
}

